namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}}
void ScriptSession::tinkerVolley(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(u->removing || number(u->life)<=0 || !u->cast || u->cast->ticket!=cast.ticket || u->owner!=cast.owner)return;if(tinkerVolleys_.size()>=4096)throw std::runtime_error("Tinker missile volley budget exceeded");auto& s=cast.spell;TinkerVolley volley;volley.spell=s;volley.source=id;volley.owner=cast.owner;volley.origin={u->x,u->y};volley.point=cast.point;volley.height=u->displayFlyHeight()+definitions().number(u->type,"UnitWeapons","launchZ",60);volley.duration=std::max(1.f/32,std::hypot(number(cast.point.x)-number(u->x),number(cast.point.y)-number(u->y))/s.speed);
    for(unsigned i=0;i<(s.kind==SpellKind::PocketFactory?1:s.shards);++i){TinkerBottle bottle;bottle.endpoint=cast.point;if(s.kind==SpellKind::ClusterRockets){float angle=float(double(random())/4294967296.*6.28318530718),radius=std::sqrt(float(double(random())/4294967296.))*s.area;bottle.endpoint=requireWorld().clamp({real(number(cast.point.x)+std::cos(angle)*radius),real(number(cast.point.y)+std::sin(angle)*radius)});}bottle.distance=std::hypot(number(bottle.endpoint.x)-number(volley.origin.x),number(bottle.endpoint.y)-number(volley.origin.y));bottle.effect=createEffect(s.missile,volley.origin,0,{},false).bits;if(bottle.effect){auto effect=effects_.at(bottle.effect);effect->z=volley.height;effect->facing=std::atan2(number(bottle.endpoint.y)-number(volley.origin.y),number(bottle.endpoint.x)-number(volley.origin.x));}volley.bottles.push_back(bottle);}tinkerVolleys_.emplace(++spellTicket_,std::move(volley));
}
void ScriptSession::tinkerVolleyImpact(const TinkerVolley& volley){
    auto& s=volley.spell;if(s.kind==SpellKind::PocketFactory){auto point=summonPoint(volley.point,s.summonType);if(!point)return;auto created=createUnit(volley.owner,s.summonType,point->x,point->y,real(0));if(!alive(created.bits,NativeKind::Unit))return;auto u=units_.at(created.bits);if(u->removing || number(u->life)<=0 || u->owner!=volley.owner || u->type!=s.summonType)return;u->summoner=volley.source;u->summonAbility=s.ability;u->timedLife=TimedLife{s.buff,s.summonDuration,s.summonDuration,false};if(s.buff)u->abilities[s.buff]=1;PocketFactoryState state;state.spell=s;state.ticket=++spellTicket_;state.death=u->deathRevision;state.owner=u->owner;state.nextSpawn=s.period;factories_[created.bits]=std::move(state);u->animation="Birth";u->animationTime=0;u->animationQueue={"Stand"};summonedEvent(volley.source,created.bits,volley.owner);return;}
    UnitState source;source.handle=volley.source;source.owner=volley.owner;std::vector<std::pair<float,std::uint32_t>> choices;for(auto& [id,u]:units_){float distance=std::hypot(number(u->x)-number(volley.point.x),number(u->y)-number(volley.point.y));if(distance<=s.area+u->collision && spellTarget(source,*u,s,false,volley.owner))choices.emplace_back(distance,id);}std::sort(choices.begin(),choices.end());float allocated=0;
    for(auto [distance,id]:choices){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!spellTarget(source,*u,s,false,volley.owner) || std::hypot(number(u->x)-number(volley.point.x),number(u->y)-number(volley.point.y))>s.area+u->collision)continue;float amount=s.amount;if(s.maxDamage>0)amount=std::min(amount,std::max(0.f,s.maxDamage-allocated));if(amount<=0)continue;allocated+=amount;auto death=u->deathRevision;damageUnit(volley.source,id,amount*(u->building?s.buildingFactor:1),0,14,false,false,nullptr,false,true,volley.owner);if(alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->deathRevision==death)applyBuff(id,volley.source,s,BuffKind::Stun);}
}
void ScriptSession::factorySpawn(std::uint32_t id,std::uint64_t ticket){
    auto found=factories_.find(id);if(found==factories_.end() || found->second.ticket!=ticket || !alive(id,NativeKind::Unit))return;auto state=found->second;auto factory=units_.at(id);auto current=[&]{return alive(id,NativeKind::Unit) && !factory->removing && number(factory->life)>0 && factory->owner==state.owner && factory->deathRevision==state.death && factories_.contains(id) && factories_.at(id).ticket==ticket;};if(!current())return;auto& s=state.spell;auto point=summonPoint({factory->x,factory->y},s.spawnType,s.spawnOffset);if(!point)return;auto created=createUnit(factory->owner,s.spawnType,point->x,point->y,factory->facing);if(!alive(created.bits,NativeKind::Unit))return;auto u=units_.at(created.bits);if(!current() || u->removing || number(u->life)<=0 || u->owner!=state.owner || u->type!=s.spawnType){if(!u->removing && u->owner==state.owner)removeUnit(created.bits);return;}u->summoner=id;u->summonAbility=s.ability;u->timedLife=TimedLife{s.guardBuff,s.spawnDuration,s.spawnDuration,false};if(s.guardBuff)u->abilities[s.guardBuff]=1;clockwerks_[created.bits]={id,ticket,u->deathRevision,u->ownerRevision,{factory->x,factory->y},s.spawnLeash,0};summonedEvent(id,created.bits,state.owner);if(!current() || !alive(created.bits,NativeKind::Unit) || u->removing || number(u->life)<=0 || u->owner!=state.owner)return;if(factory->rally){auto destination=*factory->rally;if(alive(factory->rallyTarget,NativeKind::Unit)){auto target=units_.at(factory->rallyTarget);destination={target->x,target->y};if(enemy(u->owner,target->owner) && attackUnit(created.bits,factory->rallyTarget))return;}attackMove(created.bits,destination);}
}
void ScriptSession::selfDestructDeath(const UnitState& victim){
    if(victim.illusion || !alive(victim.handle,NativeKind::Unit))return;auto current=units_.at(victim.handle);if(current->removing || current->deathRevision!=victim.deathRevision || number(current->life)>0)return;for(auto [ability,level]:victim.abilities)if(level>0 && definitions().field(ability,"AbilityData","code",ObjectData::name(ability))=="Asds"){if(tinkerExplosions_.size()>=4096)throw std::runtime_error("Self Destruct explosion budget exceeded");auto s=spellInfo(ability,unsigned(level));tinkerExplosions_.emplace(++spellTicket_,TinkerExplosion{s,victim.handle,victim.owner,{victim.x,victim.y},simulationTime_+s.duration});if(s.explodeCorpse){current->exploded=true;if(current->corpse){current->corpse->flags=0;current->corpse->consumed=true;}}break;}
}
void ScriptSession::tinkerExplosion(const TinkerExplosion& explosion){
    auto& s=explosion.spell;UnitState source;source.handle=explosion.source;source.owner=explosion.owner;spellVisual(s,"EffectArt",0,explosion.point);std::vector<std::uint32_t> targets;for(auto& [id,u]:units_)if(id!=explosion.source && spellTarget(source,*u,s,false,explosion.owner) && std::hypot(number(u->x)-number(explosion.point.x),number(u->y)-number(explosion.point.y))<=s.halfArea+u->collision)targets.push_back(id);for(auto id:targets){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!spellTarget(source,*u,s,false,explosion.owner))continue;float distance=std::hypot(number(u->x)-number(explosion.point.x),number(u->y)-number(explosion.point.y));if(distance>s.halfArea+u->collision)continue;float damage=(distance<=s.fullArea+u->collision?s.initialDamage:s.extraDamage)*(u->building?s.buildingFactor:1);damageUnit(explosion.source,id,damage,3,22,false,false,nullptr,false,true,explosion.owner);}
    if(!s.allowed.contains("tree") && !s.allowed.contains("debris"))return;std::vector<std::uint32_t> props;for(auto& [id,d]:destructables_)if(!d->removed && d->life>0 && !d->invulnerable && (d->tree?s.allowed.contains("tree"):s.allowed.contains("debris")) && std::hypot(number(d->position.x)-number(explosion.point.x),number(d->position.y)-number(explosion.point.y))<=s.halfArea+d->radius)props.push_back(id);for(auto id:props)if(alive(id,NativeKind::Destructable)){auto d=destructables_.at(id);if(d->removed || d->life<=0 || d->invulnerable)continue;float distance=std::hypot(number(d->position.x)-number(explosion.point.x),number(d->position.y)-number(explosion.point.y));destructableLife(id,d->life-(distance<=s.fullArea+d->radius?s.initialDamage:s.extraDamage));}
}
void ScriptSession::tinkerTick(double delta){
    std::vector<std::uint64_t> volleys,explosions;for(auto& [id,v]:tinkerVolleys_)volleys.push_back(id);for(auto& [id,e]:tinkerExplosions_)if(e.due<=simulationTime_)explosions.push_back(id);for(auto id:explosions){auto found=tinkerExplosions_.find(id);if(found==tinkerExplosions_.end())continue;auto explosion=std::move(found->second);tinkerExplosions_.erase(found);tinkerExplosion(explosion);}
    for(auto id:volleys){auto found=tinkerVolleys_.find(id);if(found==tinkerVolleys_.end())continue;auto volley=std::move(found->second);tinkerVolleys_.erase(found);volley.elapsed+=delta;bool complete=true;for(auto& bottle:volley.bottles){float duration=std::max(1.f/32,bottle.distance/volley.spell.speed),fraction=std::clamp(float(volley.elapsed)/duration,0.f,1.f);complete&=fraction>=1;if(auto effect=effects_.find(bottle.effect);effect!=effects_.end()){effect->second->point={real(number(volley.origin.x)+(number(bottle.endpoint.x)-number(volley.origin.x))*fraction),real(number(volley.origin.y)+(number(bottle.endpoint.y)-number(volley.origin.y))*fraction)};effect->second->z=volley.height*(1-fraction)+volley.spell.missileArc*bottle.distance*std::sin(3.14159265359f*fraction);}if(fraction>=1 && bottle.effect){destroyEffect(bottle.effect);bottle.effect=0;}}if(!volley.delivered && volley.elapsed+1e-7>=volley.duration){volley.delivered=true;tinkerVolleyImpact(volley);}if(!complete || !volley.delivered)tinkerVolleys_.emplace(id,std::move(volley));}
    std::vector<std::uint32_t> factories,children;for(auto& [id,f]:factories_)factories.push_back(id);for(auto& [id,c]:clockwerks_)children.push_back(id);for(auto id:factories){auto found=factories_.find(id);if(found==factories_.end())continue;if(!alive(id,NativeKind::Unit)){factories_.erase(found);continue;}auto u=units_.at(id);auto& state=found->second;if(u->removing || number(u->life)<=0 || u->deathRevision!=state.death || u->type!=state.spell.summonType){factories_.erase(found);continue;}if(u->paused || u->hidden())continue;if(u->owner!=state.owner){state.owner=u->owner;state.ticket=++spellTicket_;}state.elapsed+=delta;auto ticket=state.ticket;if(state.elapsed+1e-7>=state.nextSpawn){state.nextSpawn=state.elapsed+state.spell.period;factorySpawn(id,ticket);}}
    for(auto id:children){auto found=clockwerks_.find(id);if(found==clockwerks_.end())continue;if(!alive(id,NativeKind::Unit)){clockwerks_.erase(found);continue;}auto u=units_.at(id);auto& state=found->second;if(u->removing || number(u->life)<=0 || u->deathRevision!=state.death || u->ownerRevision!=state.ownership){clockwerks_.erase(found);continue;}if(u->paused || u->stunned() || u->hidden() || u->cast || simulationTime_<state.nextCheck)continue;state.nextCheck=simulationTime_+.25;if(auto parent=factories_.find(state.factory);parent!=factories_.end() && parent->second.ticket==state.factoryTicket && alive(state.factory,NativeKind::Unit)){auto factory=units_.at(state.factory);state.home={factory->x,factory->y};}float dx=number(u->x)-number(state.home.x),dy=number(u->y)-number(state.home.y),distance=std::hypot(dx,dy);if(state.leash>0 && distance>state.leash+u->collision){auto point=WorldPoint{real(number(state.home.x)+dx/distance*state.leash*.8f),real(number(state.home.y)+dy/distance*state.leash*.8f)};moveUnit(id,point);}}
}
